import{z as i,x as d,o as r,c as p,q as t,j as n,D as e,d as A,s as o,S as l,b as s}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"DNS 记录类型","description":"","frontmatter":{"title":"DNS 记录类型","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dns-rr.md","filePath":"cs/dns-rr.md","lastUpdated":1791413859000}'),B={name:"cs/dns-rr.md"};function D(c,a,N,T,C,h){const E=d("Mermaid");return r(),p("div",null,[a[2]||(a[2]=t('<h1 id="dns-记录类型" tabindex="-1">DNS 记录类型 <a class="header-anchor" href="#dns-记录类型" aria-label="Permalink to &quot;DNS 记录类型&quot;">​</a></h1><div class="epigraph"><p>同一名字下可以挂地址、别名、邮件交换、名字服务器；类型决定答案是什么对象，而不只是「有没有这个名字」。</p><footer>—— 据 RFC 1035 的 RR 格式；Kurose and Ross 对常用记录的整理</footer></div><p><a href="/cs/dns-recursive">上一课</a>走完递归与迭代。本课不重画根到权威。缺口是应答里的资源记录（RR）：A/AAAA 是地址，NS 是下一层权威，CNAME 是别名，MX 是邮件，TXT 是文本约定。解析器按<strong>问的类型</strong>取子集。本课不把 HTTP 方法提前。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/cs/dns">DNS</a> 说「得到地址或其他记录」。若只有 A，<a href="/cs/ipv6-contrast">IPv6</a> 的双栈无法表达；若 CNAME 与 NS 在区顶混用，委托会坏。每条 RR 有所有者、类型、类、TTL、数据。缺口是<strong>类型作为模式</strong>，让后课 CDN 用同一名字返回不同地址成为合法，而不是协议外魔法。</p><p><span class="marginnote">术语翻译：把每条资源记录想成一张索引卡，固定五栏——名字（所有者）、类型、TTL 保质期、类别（几乎恒为 IN）、值。问「类型 A」就是只在「地址卡」抽屉里翻；同一名字在别的抽屉里还可以有 MX 卡、TXT 卡。</span></p><p><span class="marginnote">CNAME 的目标要再查。别名链有深度限制。SOA 描述区的权威参数，不是给浏览器打开网页用的。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>查询：名字 + 类型。权威返回匹配 RR，以及胶水（NS 的 A/AAAA）以便解析器继续。否定缓存（NSEC 等属 DNSSEC 一线）本课只承认「不存在也要记一会儿」。应用选类型：浏览器要 A/AAAA，邮件要 MX。</p><p><span class="marginnote">常见误区：想在 example.com 本尊上挂 CNAME 指向 CDN。区顶必须放 SOA 和 NS 才能完成委托，而 CNAME 不允许与其他记录并存——所以厂商发明了 ANAME/ALIAS 一类变通，或让你直接把 A 记录指向它们的入口 IP。</span></p>',10)),(r(),n(l,null,{default:e(()=>[o(E,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%90%8D%E5%AD%97%E5%8A%A0%E7%B1%BB%E5%9E%8B%22%5D%20--%3E%20AUTH%5B%22%E6%9D%83%E5%A8%81%E6%88%96%E7%BC%93%E5%AD%98%22%5D%0A%20%20AUTH%20--%3E%20A%5B%22A%20%2F%20AAAA%20%E5%9C%B0%E5%9D%80%22%5D%0A%20%20AUTH%20--%3E%20NS%5B%22NS%20%E5%A7%94%E6%89%98%22%5D%0A%20%20AUTH%20--%3E%20CN%5B%22CNAME%20%E5%86%8D%E8%A7%A3%E6%9E%90%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("h2",{id:"机制",tabindex:"-1"},[A("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=s("p",null,[A("RR 把层次名字从「一台主机」扩成「一组类型化属性」。"),s("a",{href:"/cs/cdn-intuition"},"任播与 CDN"),A(" 后课会改 A/AAAA 的值或 NS 指向，类型系统不变。校验：UDP DNS 有长度与截断；真实性不是 RR 自带的，后课 TLS 用证书绑名字。")],-1)),(r(),n(l,null,{default:e(()=>[o(E,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%20www.shop.com%20%E7%9A%84%20A%20%E8%AE%B0%E5%BD%95%22%5D%20--%3E%20C1%5B%22%E7%AD%94%EF%BC%9A%E5%AE%83%E6%98%AF%20CNAME%EF%BC%8C%E6%8C%87%E5%90%91%20shop.cdn.net%22%5D%0A%20%20C1%20--%3E%20Q2%5B%22%E8%A7%A3%E6%9E%90%E5%99%A8%E7%BB%A7%E7%BB%AD%E6%9F%A5%20shop.cdn.net%20%E7%9A%84%20A%22%5D%0A%20%20Q2%20--%3E%20A1%5B%22%E7%AD%94%EF%BC%9A%E4%B8%A4%E4%B8%AA%20A%20%E5%9C%B0%E5%9D%80%22%5D%0A%20%20A1%20--%3E%20F%5B%22%E5%88%AB%E5%90%8D%E9%93%BE%E6%8A%98%E5%8F%A0%E8%BF%9B%E6%9C%80%E7%BB%88%E5%BA%94%E7%AD%94%E4%BA%A4%E7%BB%99%E5%AE%A2%E6%88%B7%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">为什么重要：CNAME 意味着「多一轮查询」。别名链每多一节，冷缓存时解析就多一次往返，太长还会撞深度上限。CDN 建议把 CNAME 目标设在自己域内并靠递归端缓存兜住，就是在控制这条链的成本。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把全部类型注册表写进主干，不引入 SVCB/HTTPS 的全部键。对资源做 GET 的应用协议下一课 HTTP。</p><p>后课默认：解析结果是带类型的记录集。网页与 API 的方法与状态码是另一层。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RR 以类型区分地址、委托、别名等。</li><li>查询必须带类型；CNAME 触发后续查找。</li><li>应用层 HTTP 下一课。</li><li>出处：RFC 1034/1035；Kurose and Ross。</li></ul>',6))])}const u=i(B,[["render",D]]);export{S as __pageData,u as default};
